__NUXT_JSONP__("/anticorrupcion/eventos/por_votacion_ethos_fue_elegido_para_formar_parte_del_comite_directivo_de_la_repca", (function(a,b,c,d,e){return {data:[{post:{slug:"por_votacion_ethos_fue_elegido_para_formar_parte_del_comite_directivo_de_la_repca",title:"Por votación, Ethos fue elegido para formar parte del Comité Directivo de la REPCA",date:"2023-06-01T20:13:55.716Z",img:"https:\u002F\u002Fucarecdn.com\u002Fef8282d1-9f78-4d16-bceb-da88d922ee4a\u002F","img-alt":"REPCA",autor:"Ethos",category:"anticorrupcion",extracto:"El Comité Directivo de la REPCA se elige por votación de todos sus integrantes y es el encargado de la coordinación de esta red anticorrupción del Comité de Participación Ciudadana del Sistema Nacional Anticorrupción.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La Red Nacional de Participación Ciudadana Anticorrupción (REPA) del Comité de Participación Ciudadana (CPC) Nacional, realizó la votación para elegir a su Comité Directivo, del que forman parte las personas integrantes del CPC y cinco representantes de organzaciones de la sociedad civil."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"De esta manera,  Ethos Innovación en Políticas Públicas, Código Transparencia, Red Académica de Gobierno Abierto México, Inteligencia Colectiva y DML Derechos Humanos y Litigio Estratégico Mexicanos son las OSC que forman parte de este Comité, al lado de Jorge Alberto Alatorre Flores; Magdalena Verónica Rodríguez Castillo; Vania Pérez Morales y Blanca Patricia Talavera Torres, del CPC."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Es importante recordar que la REPCA nació con el propósito “de acercar al CPC y a las OSC, con la finalidad de potencializar esfuerzos, mediante trabajo colaborativo, con perspectiva de género, derechos humanos, igualdad sustantiva, participación ciudadana y un enfoque de interculturalidad, en materia anticorrupción.”"}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fpor_votacion_ethos_fue_elegido_para_formar_parte_del_comite_directivo_de_la_repca",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2023-09-12T15:29:17.048Z")));